public boolean validateUnitOfMeasure()
{
    boolean ret = next validateUnitOfMeasure();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (ret == false && this.UnitAppliesToAll == NoYes::Yes)
        {
            infolog.clear(infolog.line() - 1);
            return true;
        }
    }

    return ret;
}

protected boolean validateDiscPct()
{
    boolean ret = next validateDiscPct();

    return this.removeGupErrorMessage(ret);

}

protected boolean validateDiscAmount()
{
    boolean ret = next validateDiscAmount();

    return this.removeGupErrorMessage(ret);
}

private boolean removeGupErrorMessage(boolean ret)
{
    if (ret == false && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailDiscountOfferTypeBase discountType = RetailPeriodicDiscount::findByOfferId(this.OfferId).PeriodicDiscountType;

        boolean isCreatingDiscountLineOffer = !this.PriceAttributeGroupCombinationRecId &&
                                              (discountType == RetailDiscountOfferTypeBase::DiscountOffer ||
                                               discountType == RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit);

        if (discountType == RetailDiscountOfferTypeBase::Promotion || isCreatingDiscountLineOffer)
        {
            infolog.clear(infolog.line() - 1);
            return true;
        }
    }

    return ret;
}
